function load(p){project=p;project.customAssets??=[];project.missions??=[{slot:"hero",name:"Hero",enabled:false,objective:"reach_goal",description:"Reach the goal",count:1,target:"",nextStage:p.stage,icon:null,voice:null},{slot:"neutral",name:"Neutral",enabled:false,objective:"reach_goal",description:"Reach the goal",count:1,target:"",nextStage:p.stage,icon:null,voice:null},{slot:"dark",name:"Dark",enabled:false,objective:"reach_goal",description:"Reach the goal",count:1,target:"",nextStage:p.stage,icon:null,voice:null}];hiddenClasses=new Set(p.editor?.hiddenClasses||[]);reference=p.reference||[];templates=clone(p.nativeTemplates||p.objects.filter(o=>o.kind==='native'));history=[];future=[];selected=null;dirty=false;placing=null;drawing=false;dispose(refs);dispose(collisionRefs);referenceMaterials=project.materials.map(m=>material(m,{alphaTest:.1}));for(const m of reference)(m.collision?collisionRefs:refs).add(referenceNode(m));rebuildAuthored();$('projectName').value=p.name;$('saveState').textContent='Project loaded';renderPalette();renderHierarchy();renderInspector();renderMaterials();renderScripts();renderMissions();renderCustomAssets();renderSavedObjects();updateStats();const start=p.objects[0]?.position||[0,0,0];orbit.target.set(...start);camera.position.set(start[0]+450,start[1]+350,start[2]+550);if(p.editor?.camera){camera.position.fromArray(p.editor.camera.position);orbit.target.fromArray(p.editor.camera.target)}orbit.update();message(`Opened ${p.name}: ${p.objects.length} native placements; ${reference.length} reference meshes.`,'success');status('Stage ready · choose an item or draw a shape');loadStageModels(p.stage)}
function serializable(){project.name=$('projectName').value||'Untitled stage';project.editor={...project.editor,hiddenClasses:[...hiddenClasses],camera:{position:camera.position.toArray(),target:orbit.target.toArray()}};return {...project,reference:undefined}}
async function save(){if(!project)return;await api('/api/save',serializable());dirty=false;const t=new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});$('saveState').textContent='Saved '+t;status('Project saved');message(`Saved "${project.name}" at ${t}. Reopen it any time: Open stage → Your projects (or click the game stage and choose to continue).`,'success')}

