function mode(m){gizmo.setMode(m);for(const [id,v]of[['moveTool','translate'],['rotateTool','rotate'],['scaleTool','scale']])$(id).classList.toggle('active',m===v);$('selectTool').classList.remove('active')}
function deleteSelected(){const o=item();if(!o)return;snapshot();for(const key of ['objects','geometry','paths','triggers'])project[key]=project[key].filter(x=>x.id!==o.id);selected=null;rebuildAuthored();renderInspector();changed()}
function duplicate(){const o=item();if(!o)return;snapshot();const copy=clone(o);copy.id=uuid();copy.name+=' copy';copy.position[0]+=50;const key=o.kind==='geometry'?'geometry':o.kind==='trigger'?'triggers':o.kind==='path'?'paths':'objects';project[key].push(copy);(o.kind==='geometry'?authored:objects).add(makeNode(copy));select(copy.id);changed()}
function restore(next,opposite){if(!next.length)return;opposite.push(clone({...project,reference:undefined}));project=next.pop();project.reference=reference;if(!item())selected=null;rebuildAuthored();renderInspector();renderMaterials();renderScripts();changed()}
function updateStats(){if(!project)return;$('count').textContent=all().length;const triangles=project.geometry.reduce((n,g)=>n+g.triangles.length,0);$('stats').textContent=`${project.objects.length} placements · ${triangles.toLocaleString()} authored triangles`}
function field(label,key,value,type='number',extra=''){return`<label class="field">${esc(label)}<input data-key="${key}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function vector(label,key,values){return`<div class="note">${label}</div><div class="vector">${values.map((v,i)=>`<label>${'XYZ'[i]}<input type="number" step="1" data-vector="${key}" data-axis="${i}" value="${Number(v).toFixed(2)}"></label>`).join('')}</div>`}
