let showRange=false;const rangeRing=new THREE.Mesh(new THREE.RingGeometry(.985,1,96),new THREE.MeshBasicMaterial({color:0xf0c040,transparent:true,opacity:.7,side:THREE.DoubleSide,depthTest:false}));rangeRing.rotation.x=-Math.PI/2;rangeRing.visible=false;rangeRing.renderOrder=10;scene.add(rangeRing);
function updateRange(){const o=item();if(!showRange||!o||o.kind!=='native'||!o.render){rangeRing.visible=false;return}const r=o.render*100;rangeRing.scale.set(r,r,1);rangeRing.position.set(...o.position);rangeRing.visible=true}
function dropToGround(o){const from=new THREE.Vector3(o.position[0],o.position[1]+30,o.position[2]);const ray=new THREE.Raycaster(from,new THREE.Vector3(0,-1,0),0,100000);const targets=[];collisionRefs.traverse(c=>{if(c.isMesh)targets.push(c)});authored.traverse(c=>{if(c.isMesh)targets.push(c)});
 const hit=ray.intersectObjects(targets,false).find(h=>h.distance>0.01);if(!hit){message(`${o.name}: no collision surface below it.`,'warning');return}snapshot();o.position[1]=Math.round(hit.point.y*100)/100;replaceNode(o);changed();renderInspector();updateRange();message(`${o.name} dropped to y ${o.position[1]}.`,'success')}
