function showPanel(name){$('bottomPanel').style.height=name==='graph'?'330px':['missions','customAssets','objectLibrary','stageSettings','models'].includes(name)?'360px':'180px';for(const p of ['messages','assets','graph','scripts','missions','customAssets','objectLibrary','stageSettings','models']){const panel=$(p);if(panel)panel.hidden=p!==name}document.querySelectorAll('.bottomTabs button').forEach(b=>b.classList.toggle('active',b.dataset.panel===name));if(name==='graph')renderGraph()}
async function openDialog(){config=await api('/api/config');$('stageList').replaceChildren();const q=$('stageSearch').value.toLowerCase();for(const s of config.stages.filter(s=>s.name.toLowerCase().includes(q))){const b=document.createElement('button');b.className='stageButton';b.innerHTML=`<b>${esc(s.name)}</b><small>${s.id}</small><span>Open →</span>`;b.onclick=()=>openStage(s.id);$('stageList').append(b)}$('projectList').replaceChildren();for(const p of config.projects){const b=document.createElement('button');b.className='stageButton';b.innerHTML=`<b>${esc(p.name)}</b><small>${esc(stageName(p.stage))} · saved ${esc(savedWhen(p.saved))}</small><span>Open →</span>`;b.onclick=()=>openProject(p.id);$('projectList').append(b)}if(!$('openDialog').open)$('openDialog').showModal()}
