function savedWhen(t){const d=new Date(t*1000),now=new Date();const time=d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});return d.toDateString()===now.toDateString()?'today '+time:d.toLocaleDateString()+' '+time}
