window.addEventListener('keydown',e=>{const ae=document.activeElement;if(e.key==='Delete'&&selected&&!(ae.tagName==='TEXTAREA'||(ae.tagName==='INPUT'&&!['checkbox','radio','button','range'].includes(ae.type)))&&!document.querySelector('dialog[open]')){e.preventDefault();ae.blur?.();deleteSelected();return}if(['INPUT','TEXTAREA','SELECT'].includes(ae.tagName))return;if(e.key==='Escape'){targetPicker=null;cancelPlacement();select(null);navKeys.clear();status('Selection cleared · WASD moves · middle mouse looks · wheel changes speed');return}if(e.shiftKey&&e.key.toLowerCase()==='f'){e.preventDefault();setFly(!fly);return}if(e.key==='Tab'){e.preventDefault();document.body.classList.toggle('focusView');return}if(e.key==='Enter'&&drawing){finishDraw();return}if(e.ctrlKey&&e.key.toLowerCase()==='s'){e.preventDefault();save();return}if(e.ctrlKey&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?restore(future,history):restore(history,future);return}if(e.key==='Delete')deleteSelected();if(e.key.toLowerCase()==='f')focus();if(e.key.toLowerCase()==='g')mode('translate');if(e.key.toLowerCase()==='r')mode('rotate');if(e.key.toLowerCase()==='t')mode('scale');if(e.ctrlKey&&e.key.toLowerCase()==='d'){e.preventDefault();duplicate()}});
