// ---- resizable layout: left / right columns, palette-vs-outliner split, bottom panel
function setupResizers(){const store=(k,v)=>{try{localStorage.setItem('sw-'+k,v)}catch{}},load=k=>{try{return localStorage.getItem('sw-'+k)}catch{return null}};
 const rootStyle=document.documentElement.style;for(const k of ['left','right','bottom','split']){const v=load(k);if(v)rootStyle.setProperty('--'+k,v)}
 // sized: the element whose real size is the start value (the CSS variable is unset until the first drag); host: where
 // the handle lives (the bottom panel scrolls, so its handle sits on the tab bar above it)
 const mk=(cls,el,axis,varName,min,max,invert=false,host=el)=>{const h=document.createElement('div');h.className='resizer '+cls;if(cls==='py')el.after(h);else host.append(h);
  h.onpointerdown=e=>{e.preventDefault();h.setPointerCapture(e.pointerId);const start=axis==='x'?e.clientX:e.clientY;const box=el.getBoundingClientRect();const cur=axis==='x'?box.width:box.height;
   h.onpointermove=m=>{const d=(axis==='x'?m.clientX:m.clientY)-start;const v=Math.max(min,Math.min(max,cur+(invert?-d:d)));rootStyle.setProperty('--'+varName,v+'px');renderer?.domElement&&dispatchEvent(new Event('resize'))};
   h.onpointerup=()=>{h.onpointermove=null;store(varName,getComputedStyle(document.documentElement).getPropertyValue('--'+varName).trim())}}};
 mk('rx',document.querySelector('.palette'),'x','left',180,560);mk('lx',document.querySelector('.inspector'),'x','right',220,620,true);
 mk('ty',document.querySelector('#bottomPanel'),'y','bottom',90,Math.max(600,Math.round(innerHeight*.75)),true,document.querySelector('.bottomTabs'));mk('py',$('paletteItems'),'y','split',90,900)}
