function classKey(o){return o.kind==='native'?`native-${o.list}-${o.type}`:o.kind==='geometry'?`shape-${o.shape||'mesh'}`:o.kind}
function classLabel(o){return o.kind==='native'?(config.catalog.find(c=>c.list===o.list&&c.type===o.type)?.name||`Object ${o.list}:${o.type}`):o.kind==='geometry'?`${o.shape||'Custom'} geometry`:(o.script?'Script objects':{destination:'Teleport destinations',playerstart:'Player starts (game)',goalpose:'Finish poses',spawn:'Workshop start overrides',teleport:'Teleport pads',trigger:'Trigger volumes',path:'Paths / rails'}[o.kind]||o.kind)}
function actuallyVisible(n){while(n){if(!n.visible)return false;n=n.parent}return true}
function applyVisibility(){for(const o of all()){const n=nodes.get(o.id);if(n)n.visible=o.enabled!==false&&!hiddenClasses.has(classKey(o))}if(selected&&!nodes.get(selected)?.visible){select(null)}renderVisibility()}
// Visibility: categories (each can be expanded to its object types), then the stage art chunks.
const visOpen=new Set();
function visCategory(o){if(o.kind==='native')return cbCategory(o.list,o.type,o.nativeName||o.name);return {geometry:'shapes',trigger:'logic',path:'paths',spawn:'key',teleport:'key',goalpose:'key',playerstart:'key',destination:'logic'}[o.kind]||'objects'}
const VIS_LABELS={key:'Key items (start, goal, checkpoints, finish poses)',pickups:'Pickups',objects:'Objects',enemies:'Enemies',volumes:'Invisible volumes (lights, triggers, wind, sound)',decor:'Decor & breakables',shapes:'Your shapes',logic:'Your trigger volumes',paths:'Paths / rails'};
function renderVisibility(){const p=document.getElementById('classList');if(!p||!project)return;const q=document.getElementById('classSearch').value.toLowerCase();p.replaceChildren();
 const cats=new Map();for(const o of all()){const c=visCategory(o),k=classKey(o);if(!cats.has(c))cats.set(c,new Map());const m=cats.get(c);if(!m.has(k))m.set(k,{name:classLabel(o),count:0});m.get(k).count++}
 const row=(text,checked,indeterminate,onchange,cls,toggle)=>{const label=document.createElement('label');label.className='visibilityRow '+(cls||'');if(toggle){const b=document.createElement('b');b.textContent=toggle.open?'▾':'▸';b.onclick=e=>{e.preventDefault();toggle.fn()};label.append(b)}const cb=document.createElement('input');cb.type='checkbox';cb.checked=checked;cb.indeterminate=indeterminate;cb.onchange=()=>onchange(cb.checked);label.append(cb,document.createTextNode(text));p.append(label)};
 for(const c of Object.keys(VIS_LABELS)){const m=cats.get(c);if(!m)continue;const keys=[...m.keys()],shown=keys.filter(k=>!hiddenClasses.has(k)).length,total=[...m.values()].reduce((n,x)=>n+x.count,0);
  if(q&&!VIS_LABELS[c].toLowerCase().includes(q)&&![...m.values()].some(x=>x.name.toLowerCase().includes(q)))continue;
  const open=visOpen.has(c)||!!q;row(`${VIS_LABELS[c]} (${total})`,shown>0,shown>0&&shown<keys.length,on=>{for(const k of keys)on?hiddenClasses.delete(k):hiddenClasses.add(k);applyVisibility();setDirty()},'visCat',{open,fn:()=>{open?visOpen.delete(c):visOpen.add(c);renderVisibility()}});
  if(open)for(const [k,x] of [...m].sort((a,b)=>a[1].name.localeCompare(b[1].name))){if(q&&!x.name.toLowerCase().includes(q))continue;row(`${x.name} (${x.count})`,!hiddenClasses.has(k),false,on=>{on?hiddenClasses.delete(k):hiddenClasses.add(k);applyVisibility();setDirty()},'visChild')}}
 const chunks=project.native.chunks||[];const art=chunks.filter(c=>!c.backdrop),back=chunks.filter(c=>c.backdrop);
 for(const [id,label,list] of [['art','Stage art chunks',art],['back','Skybox / backdrop layers',back]]){if(!list.length)continue;const keys=list.map(c=>'chunk-'+c.number),shown=keys.filter(k=>!hiddenClasses.has(k)).length,open=visOpen.has(id);
  const setChunk=(n,on)=>{const k='chunk-'+n;on?hiddenClasses.delete(k):hiddenClasses.add(k);for(const group of [refs,collisionRefs,killRefs])for(const mesh of group.children)if(mesh.userData.chunk===n)mesh.visible=on&&(mesh.userData.kill?showKill:backdropVisible(mesh))};
  row(`${label} (${list.length})`,shown>0,shown>0&&shown<keys.length,on=>{for(const c of list)setChunk(c.number,on);setDirty();renderVisibility()},'visCat',{open,fn:()=>{open?visOpen.delete(id):visOpen.add(id);renderVisibility()}});
  if(open)for(const c of list)row(`Chunk ${c.number}${c.backdrop?` - ${c.span.toLocaleString()} wide`:''}`,!hiddenClasses.has('chunk-'+c.number),false,on=>{setChunk(c.number,on);setDirty()},'visChild')}
 const kills=killRefs.children;if(kills.length){const n=kills.reduce((a,m)=>a+m.userData.faceMap.length,0);row(`Kill planes - falling / death (${n} faces)`,showKill,false,on=>{showKill=on;for(const m of kills)m.visible=on&&!hiddenClasses.has('chunk-'+m.userData.chunk);renderVisibility()},'visCat')}
 const standins=refs.children.filter(m=>m.userData.standin);if(standins.length)row(`Distant stand-ins - flat P layers (${standins.length})`,showStandins,false,on=>{showStandins=on;for(const m of standins)m.visible=on&&!hiddenClasses.has('chunk-'+m.userData.chunk);renderVisibility()},'visCat')}
// Skybox / backdrop layers. In game, "Trigger Skybox" objects (class 0059: DrawMode, Radius, Chunk_1..4) switch which
// backdrop chunk is drawn as the player passes them (Glyphic Canyon: 60 at the start, 61, 62, 64 ...). "In game" here =
// the chunks of the nearest switching trigger (DrawMode 1) to the editor camera, else the first backdrop chunk.
let skyMode='game',skyActive=new Set(),skyAt=0;
// "P" worlds of ordinary chunks (e.g. STG0201_P_04): a few huge flat quads with blurry cliff textures. Likely the
// game's low-detail stand-ins for distant areas, drawn while the real neighbouring chunks are not; the editor draws
// every chunk at once, so they cover the real walls. Hidden by default (meaning not verified in game).
let showStandins=false;
function backdropVisible(mesh){if(mesh.userData.standin)return showStandins;if(!mesh.userData.backdrop)return true;return skyMode==='always'||(skyMode==='game'&&skyActive.has(mesh.userData.chunk))}
function updateSkybox(now=performance.now()){if(!project||now-skyAt<250)return;skyAt=now;const back=(project.native.chunks||[]).filter(c=>c.backdrop).map(c=>c.number);if(!back.length)return;
 let best=null,bd=Infinity;for(const o of project.objects){if(o.kind!=='native'||o.list!==0||o.type!==0x59||(paramWord(o,1)??0)!==1)continue;const d=camera.position.distanceToSquared(new THREE.Vector3(...o.position));if(d<bd){bd=d;best=o}}
 const want=new Set(best?[3,4,5,6].map(i=>paramWord(best,i)).filter(n=>back.includes(n)):[]);if(!want.size)want.add(Math.min(...back));
 const changed=want.size!==skyActive.size||[...want].some(n=>!skyActive.has(n));skyActive=want;if(!changed&&skyMode==='game')return;
 for(const mesh of refs.children)if(mesh.userData.backdrop)mesh.visible=!hiddenClasses.has('chunk-'+mesh.userData.chunk)&&backdropVisible(mesh)}
function setupSkyboxToggle(){const label=document.createElement('label');label.title='How the huge skybox / backdrop layers are shown';label.innerHTML='Skybox <select id="skyMode"><option value="game">As in game</option><option value="always">All</option><option value="hidden">Hidden</option></select>';$('viewOptions').append(label);
 $('skyMode').onchange=e=>{skyMode=e.target.value;skyAt=0;skyActive=new Set();updateSkybox()}}
