const objPicker=document.createElement('input');objPicker.type='file';objPicker.accept='.obj';objPicker.hidden=true;document.body.append(objPicker);
objPicker.onchange=async()=>{const f=objPicker.files[0];if(!f||!project)return;try{const text=await f.text(),positions=[],uv=[],vertices=[],uvs=[],triangles=[];for(const raw of text.split(/\r?\n/)){const line=raw.trim();if(!line||line[0]==='#')continue;const [type,...parts]=line.split(/\s+/);if(type==='v')positions.push(parts.slice(0,3).map(Number));else if(type==='vt')uv.push(parts.slice(0,2).map(Number));else if(type==='f'){const face=[];for(const word of parts){const [pi,ti]=word.split('/').map(Number);const p=positions[pi<0?positions.length+pi:pi-1];if(!p||p.length!==3||!p.every(Number.isFinite))throw Error('Invalid OBJ vertex');const t=uv[ti<0?uv.length+ti:ti-1]||[0,0];face.push(vertices.length);vertices.push([...p]);uvs.push([t[0],1-t[1]])}if(face.length===3)triangles.push(face);else{const ps=face.map(i=>new THREE.Vector3(...vertices[i]));const normal=new THREE.Vector3().crossVectors(ps[1].clone().sub(ps[0]),ps[2].clone().sub(ps[0]));const a=[Math.abs(normal.x),Math.abs(normal.y),Math.abs(normal.z)],drop=a.indexOf(Math.max(...a));const poly=ps.map(p=>new THREE.Vector2(...p.toArray().filter((_,i)=>i!==drop)));for(const tri of THREE.ShapeUtils.triangulateShape(poly,[]))triangles.push(tri.map(i=>face[i]))}}}if(!triangles.length)throw Error('OBJ has no faces');if(vertices.length>65535)throw Error('Split this mesh into parts below65535 vertices');snapshot();const o={...createShape('box',orbit.target.toArray()),vertices,uvs,triangles,name:f.name.replace(/\.obj$/i,''),shape:'mesh'};project.geometry.push(o);authored.add(makeNode(o));select(o.id);focus();changed();message(`Imported ${f.name}: ${vertices.length} vertices, ${triangles.length} triangles. Collision enabled.`,'success')}catch(e){message(e.message,'error')}finally{objPicker.value=''}};

