let freeLook=null;
renderer.domElement.addEventListener('pointerdown',e=>{if(![1,2].includes(e.button))return;if(e.button===1&&selected){const n=nodes.get(selected);if(n){const center=new THREE.Box3().setFromObject(n).getCenter(new THREE.Vector3());orbit.target.copy(center)}return}e.preventDefault();e.stopImmediatePropagation();orbit.enabled=false;freeLook={x:e.clientX,y:e.clientY,button:e.button};renderer.domElement.setPointerCapture(e.pointerId);try{renderer.domElement.requestPointerLock?.()}catch{}},true);
renderer.domElement.addEventListener('pointermove',e=>{if(!freeLook)return;if(!(e.buttons&(freeLook.button===2?2:4))){endFreeLook();return}const locked=document.pointerLockElement===renderer.domElement;const yaw=(locked?e.movementX:e.clientX-freeLook.x)*.004,pitch=(locked?e.movementY:e.clientY-freeLook.y)*.004;freeLook={x:e.clientX,y:e.clientY,button:freeLook.button};const angles=new THREE.Euler().setFromQuaternion(camera.quaternion,'YXZ');angles.y-=yaw;angles.x=THREE.MathUtils.clamp(angles.x-pitch,-Math.PI/2+.01,Math.PI/2-.01);camera.quaternion.setFromEuler(angles);orbit.target.copy(camera.position).addScaledVector(camera.getWorldDirection(new THREE.Vector3()),100)},true);
renderer.domElement.addEventListener('pointerup',e=>{if(freeLook&&e.button===freeLook.button){endFreeLook();try{renderer.domElement.releasePointerCapture(e.pointerId)}catch{}}},true);
// Right-drag look locks the pointer (it cannot leave the window and keep turning); any release, lost lock, or the
// window losing focus ends it. A middle-drag orbit whose button was released outside the window is ended too.
let lastPointerId=1;renderer.domElement.addEventListener('pointerdown',e=>{lastPointerId=e.pointerId},true);
function endFreeLook(){if(freeLook){freeLook=null;orbit.enabled=true}if(document.pointerLockElement===renderer.domElement)document.exitPointerLock()}
document.addEventListener('pointerlockchange',()=>{if(document.pointerLockElement!==renderer.domElement&&freeLook){freeLook=null;orbit.enabled=true}});
window.addEventListener('blur',()=>{endFreeLook();renderer.domElement.dispatchEvent(new PointerEvent('pointerup',{bubbles:true,button:1,pointerType:'mouse',pointerId:lastPointerId}))});
renderer.domElement.addEventListener('pointerenter',e=>{if(e.buttons===0&&!freeLook)renderer.domElement.dispatchEvent(new PointerEvent('pointerup',{bubbles:true,button:1,pointerType:'mouse',pointerId:lastPointerId}))});
renderer.domElement.addEventListener('wheel',e=>{if(selected)return;e.preventDefault();e.stopImmediatePropagation();flySpeed=THREE.MathUtils.clamp(flySpeed*Math.exp(-e.deltaY*.0015),1,50000);speed.value=Math.round(flySpeed);status('Move speed: '+Math.round(flySpeed)+' units/s')},{capture:true,passive:false});
