const editCollisionLabel=document.createElement('label');editCollisionLabel.innerHTML='<input id="editCollisionFaces" type="checkbox"> Edit collision faces';$('viewOptions').append(editCollisionLabel);$('editCollisionFaces').onchange=()=>{if($('editCollisionFaces').checked){$('showCollision').checked=true;collisionRefs.visible=true;status('Click an original collision face to make it editable; Delete removes it. Adjacent triangles can be edited separately.')}};
// Kill planes = collision triangles with surface flag 0x20 (Glyphic: a bowl under each chunk that curves up behind
// the play area, plus chunk 90 = one sheet under the whole stage). Proven: the user's platform dies exactly where the
// chunk 1 sheet rises through it. Own red layer, shown without the collision view; pickable for face editing.
const KILL_FLAG=0x20;let showKill=true;
function killNode(m){const faces=m.triangles.map((_,i)=>i).filter(i=>(m.flags?.[i]??0)===KILL_FLAG&&!(project.collisionEdits?.[m.id]||[]).includes(i));if(!faces.length)return null;
 const g=geometryFromData({...m,triangles:faces.map(i=>m.triangles[i]),colours:null,uvs:null});const mesh=new THREE.Mesh(g,new THREE.MeshBasicMaterial({color:0xff2a3a,transparent:true,opacity:.28,depthWrite:false,side:THREE.DoubleSide}));
 mesh.add(new THREE.LineSegments(new THREE.EdgesGeometry(g,1),new THREE.LineBasicMaterial({color:0xff5060,transparent:true,opacity:.7})));
 mesh.userData.reference=true;mesh.userData.kill=true;mesh.userData.referenceId=m.id;mesh.userData.faceMap=faces;mesh.userData.chunk=m.chunk;mesh.visible=showKill&&!hiddenClasses.has('chunk-'+m.chunk);return mesh}
function rebuildCollisionReferences(){if(!project)return;dispose(collisionRefs);dispose(killRefs);for(const m of reference.filter(m=>m.collision)){collisionRefs.add(referenceNode(m));const k=killNode(m);if(k)killRefs.add(k)}}
function editCollisionFace(hit){const source=reference.find(m=>m.id===hit.object.userData.referenceId);const face=hit.object.userData.faceMap[hit.faceIndex];if(!source||face===undefined)return;const vertices=source.triangles[face].map(i=>[...source.vertices[i]]);const center=vertices.reduce((a,v)=>a.map((x,i)=>x+v[i]/3),[0,0,0]);snapshot();project.collisionEdits??={};project.collisionEdits[source.id]??=[];project.collisionEdits[source.id].push(face);const o={...createShape('box',center),shape:'collision',name:'Collision face '+face,vertices:vertices.map(v=>v.map((x,i)=>x-center[i])),triangles:[[0,1,2]],uvs:[[0,0],[1,0],[0,1]],renderVisible:false,chunk:source.chunk,surface:source.flags?.[face]||2};project.geometry.push(o);$('editCollisionFaces').checked=false;rebuildAuthored();select(o.id);changed();message('Original collision face replaced by an editable invisible triangle. Move, rotate, scale, edit vertices, or Delete it.','success')}

