const pageId=(crypto.randomUUID?crypto.randomUUID():String(Math.random()).slice(2)+Date.now()).replace(/-/g,'').slice(0,32);
const lifeUrl=kind=>`/api/${kind}?t=${encodeURIComponent(config?.token||'')}&page=${pageId}`;
function alive(){if(config?.token)fetch(lifeUrl('alive')).catch(()=>{})}
alive();setInterval(alive,4000);
addEventListener('pagehide',()=>{if(config?.token)fetch(lifeUrl('bye'),{keepalive:true}).catch(()=>{})});

